query Issues($first: Int = 20, $after: String, $ids: [ID!], $projectId: [ID!], $status: [String!], $category: [String!]) {
  issues(
    first: $first
    after: $after
    ids: $ids
    projectId: $projectId
    status: $status
    category: $category
  ) {
    nodes {
      id
      projectId
      parentId
      title
      description
      category
      status
      assigneeId
      dueDate
      position
      revision
      createdAt
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

