query ProjectRepositories($ids: [ID!], $first: Int = 20, $after: String) {
  projects(ids: $ids, first: $first, after: $after) {
    nodes {
      id
      name
      repositories(first: 100) {
        nodes {
          id
          nameWithOwner
          url
          path
          ref
          pullRequestActivity(first: 20) {
            error
            pullRequests {
              nodes {
                number
                title
                url
                state
                createdAt
                updatedAt
                closedAt
                mergedAt
              }
              pageInfo {
                endCursor
                hasNextPage
              }
            }
          }
        }
        pageInfo {
          endCursor
          hasNextPage
        }
      }
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query Projects($first: Int = 20, $after: String, $ids: [ID!], $active: Boolean, $archived: Boolean, $states: [String!]) {
  projects(
    first: $first
    after: $after
    ids: $ids
    active: $active
    archived: $archived
    states: $states
  ) {
    nodes {
      id
      name
      slug
      githubRepository
      goals
      openIssues
      revision
      archived
      state
      rank
      useCases {
        id
        title
        summary
        revision
      }
      customerSegments {
        id
        title
        summary
        revision
      }
      userStories: userStoryRecords {
        id
        title
        summary
        revision
      }
      goalRecords {
        id
        title
        summary
        revision
      }
      readiness {
        stage
        priority
        missing
        signals
      }
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query ProjectSummaries($first: Int = 20, $after: String, $ids: [ID!], $active: Boolean, $archived: Boolean, $states: [String!]) {
  projectSummaries: projects(
    first: $first
    after: $after
    ids: $ids
    active: $active
    archived: $archived
    states: $states
  ) {
    nodes {
      name
